head.script:
scwin.onpageload = function() {
    dataList1.setJSON([{
        col1: "col1",
        col2: "col2",
        col3: "col3",
        col4: "col4",
        col5: "col5",
        col6: "col6"
    }], false);
    scwin.setUseRealColIndex(false);
};

scwin.setUseRealColIndex = function(useRealColIndex) {
    var grid = gridView1;
    if (!grid.__waea932_getConfiguration) {
        grid.__waea932_getConfiguration = grid.getConfiguration;
    }
    grid.getConfiguration = function(key) {
        if (key === "/WebSquare/" + this.options.pluginName + "/getColumnVisible/@useRealColIndex") {
            return useRealColIndex ? "true" : "false";
        }
        return this.__waea932_getConfiguration.apply(this, arguments);
    };
};

scwin.runColumnMoveVisibleScenario = function() {
    scwin.setUseRealColIndex(false);
    gridView1.setColumnVisible("col5", false);
    var setOrderResult = gridView1.setColumnOrder([0, 1, 2, 4, 5, 3]);
    var invalidVisible = gridView1.getColumnVisible("col5555");
    return {
        setOrderResult: setOrderResult,
        columnOrder: gridView1.getColumnOrder(),
        col4Visible: gridView1.getColumnVisible("col4"),
        col5Visible: gridView1.getColumnVisible("col5"),
        invalidVisible: invalidVisible,
        invalidIsUndefined: invalidVisible === undefined
    };
};

scwin.getCol5VisibleWithRealColIndex = function() {
    scwin.setUseRealColIndex(true);
    var visible = gridView1.getColumnVisible("col5");
    scwin.setUseRealColIndex(false);
    return visible;
};
